import React, { useState } from 'react';

const QuizPage = () => {
  const [formData, setFormData] = useState({
    exam: "",
    difficultyLevels: [],
    classYear: "",
    name: "",
    quizMode: "",
    addHints: false,
    adaptiveDifficulty: false,
    answerExplanation: false,
    breakIntoSubtopics: false,
    subjects: [],
    topics: [],
    currentSubject: "",
    currentTopic: "",
    numberOfQuestions: null,
    timerOption: "noTimer", // Default timer option
    perQuestionTime: "", // Minutes per question
    totalTime: "", // Total quiz time
  });

  // Function to handle input changes
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleAddSubject = () => {
    if (formData.currentSubject.trim()) {
      setFormData((prev) => ({
        ...prev,
        subjects: [...prev.subjects, formData.currentSubject.trim()],
        currentSubject: "", // Clear the input after adding
      }));
    }
  };

  const handleAddTopic = () => {
    if (formData.currentTopic.trim()) {
      setFormData((prev) => ({
        ...prev,
        topics: [...prev.topics, formData.currentTopic.trim()],
        currentTopic: "", // Clear the input after adding
      }));
    }
  };

  const handleTimerChange = (e) => {
    const { value } = e.target;
    setFormData((prev) => ({
      ...prev,
      timerOption: value,
      perQuestionTime: "", // Reset related fields
      totalTime: "",
    }));
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    // Log the complete form data
    console.log(formData);
  };

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <h3>What should we call you?</h3>
        <input
          type="text"
          placeholder="e.g. ABC XYZ"
          name="name"
          value={formData.name}
          onChange={handleChange}
        />

        <h3>Exam Type</h3>
        <input
          type="text"
          placeholder="e.g. MidTerm, JEE"
          name="exam"
          value={formData.exam}
          onChange={handleChange}
        />

        <h3>No. of Questions</h3>
        <input
          type="number"
          placeholder="e.g. 5, 10"
          name="numberOfQuestions"
          value={formData.numberOfQuestions}
          onChange={handleChange}
        />

        {/* Difficulty Levels */}
        <label className="block font-semibold">Select Difficulty Levels</label>
        <div>
          <label>
            <input
              type="checkbox"
              value="Easy"
              checked={formData.difficultyLevels.includes("Easy")}
              onChange={handleDifficultyChange}
            />
            Easy
          </label>
          <label>
            <input
              type="checkbox"
              value="Medium"
              checked={formData.difficultyLevels.includes("Medium")}
              onChange={handleDifficultyChange}
            />
            Medium
          </label>
          <label>
            <input
              type="checkbox"
              value="Hard"
              checked={formData.difficultyLevels.includes("Hard")}
              onChange={handleDifficultyChange}
            />
            Hard
          </label>
        </div>

        {/* Timer Options */}
        <h3 className="text-lg font-semibold mb-4">Timer Options</h3>
        <div className="flex flex-col gap-2 mb-4">
          <label className="flex items-center gap-2">
            <input
              type="radio"
              name="timerOption"
              value="noTimer"
              checked={formData.timerOption === "noTimer"}
              onChange={handleTimerChange}
            />
            No Timer
          </label>

          <label className="flex items-center gap-2">
            <input
              type="radio"
              name="timerOption"
              value="perQuestion"
              checked={formData.timerOption === "perQuestion"}
              onChange={handleTimerChange}
            />
            Set Time per Question
          </label>
          {formData.timerOption === "perQuestion" && (
            <input
              type="number"
              name="perQuestionTime"
              value={formData.perQuestionTime}
              placeholder="Minutes per question"
              onChange={handleChange}
            />
          )}

          <label className="flex items-center gap-2">
            <input
              type="radio"
              name="timerOption"
              value="totalTime"
              checked={formData.timerOption === "totalTime"}
              onChange={handleTimerChange}
            />
            Set Total Time for Quiz
          </label>
          {formData.timerOption === "totalTime" && (
            <input
              type="number"
              name="totalTime"
              value={formData.totalTime}
              placeholder="Total quiz time (minutes)"
              onChange={handleChange}
            />
          )}
        </div>

        {/* Submit Button */}
        <div className="mb-4 text-center">
          <button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded-lg">
            Create Quiz
          </button>
        </div>
      </form>
    </div>
  );
};

export default QuizPage;
